Q: Passing parameters to Partial Views A: <p>It may be best to create a ViewModel type that can be used with your Edit, Create, Delete, and Details views, that holds all of the information you want to display in your main and partial views. Then you can use <code>Html.Partial</code> like I've done here near the bottom of Details.cshtml to render your partial view with the specified object as its model.</p>

<pre><code>public class Device
{
    public int DeviceID { get; set; }
    public string Name { get; set; }
    public int LocationID { get; set; }
}

public class Location
{
    public int LocationID { get; set; }
    public string Name { get; set; }
    public int DeviceID { get; set; }
}

public class DeviceDetailsViewModel
{
    public Device Device { get; set; }
    public Location Location { get; set; }
}
</code></pre>

<p><strong>Details.cshtml</strong></p>

<pre><code>@model TestAspNet.Models.DeviceDetailsViewModel

@{
    ViewBag.Title = "Details";
}

&lt;h2&gt;Details&lt;/h2&gt;

&lt;div&gt;
    &lt;span&gt;Device: @Model.Device.DeviceID&lt;/span&gt;
&lt;/div&gt;
&lt;div&gt;
    &lt;span&gt;@Model.Device.Name&lt;/span&gt;
&lt;/div&gt;
&lt;div&gt;
    @Html.Partial("_Location", Model.Location)
&lt;/div&gt;
</code></pre>

<p><strong>_Location.cshtml</strong></p>

<pre><code>@model TestAspNet.Models.Location

&lt;span class="text-success"&gt;@Model.Name&lt;/span&gt;
</code></pre>

<p><strong>DeviceController Details method</strong></p>

<pre><code>public ActionResult Details()
{
    // Create a new instance of our ViewModel class.
    var vm = new DeviceDetailsViewModel();

    // You would retrieve the Device and Location 
    // objects for the ViewModel object here.
    vm.Device = new Device();
    vm.Device.DeviceID = 1;
    vm.Device.LocationID = 2;
    vm.Device.Name = "Device Name";

    vm.Location = new Location();
    vm.Location.DeviceID = 1;
    vm.Location.LocationID = 2;
    vm.Location.Name = "Location Name";

    // Pass your ViewModel in your return
    // statement to set the model for the view.
    return View(vm);
}
</code></pre>
